#include <cstdlib>
#include <new>
namespace selection_failure {thread_local long remaining=-1;thread_local bool count=false;thread_local size_t calls=0;}
void *operator new(size_t n){if(selection_failure::count)++selection_failure::calls;if(selection_failure::remaining>=0&&selection_failure::remaining--==0){selection_failure::remaining=0;throw std::bad_alloc();}if(auto p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void *operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}void operator delete[](void*p,size_t)noexcept{std::free(p);}
#define main existing_independent_mirror_suite
#include "independent-seam-key-mirror.cpp"
#undef main
