namespace {
bool same_values(const std::vector<Vec3>&a,const std::vector<Vec3>&b){return a.size()==b.size()&&std::equal(a.begin(),a.end(),b.begin(),[](Vec3 x,Vec3 y){return same(x,y);});}
void done(Document &d){if(!d.wait_asset()||!d.wait_native_stroke()||!d.wait_mesh()||!d.frame().state->error.empty())throw std::runtime_error("Selected-key endpoint failed: "+d.frame().state->error);}
Scene source(){auto s=fixture(false);ShapeKeyEdit e;e.action=ShapeKeyAction::Replace;e.positions=s.active().painted->mesh().positions;e.positions[0].z+=.013f;e.positions[3].z-=.017f;author_shapekey(s,s.active().id,e);return s;}
NativeStrokeSample visible_ray(Document &d){auto f=d.frame();if(!f.surface->picking)throw std::runtime_error("Missing selected-key visibility query");const auto&m=f.surface->mesh;for(size_t c=0;c<m.indices.size();c+=3)for(int corner=0;corner<3;++corner){Vec3 p{};for(int k=0;k<3;++k)p+=m.positions[m.indices[c+k]]*(k==corner?.97f:.015f);NativeStrokeSample s;s.origin=p+Vec3{0,0,2};s.direction={0,0,-1};auto hit=f.surface->picking->raycast(s.origin,s.direction,4);if(hit&&length(hit->position-p)<1e-4f){s.brush.radius=.3f;s.brush.tool=Tool::Clay;return s;}}throw std::runtime_error("No real visible selected-key vertex");}
struct Hand{Document &d;SpatialFrame f;explicit Hand(Document&doc):d(doc){f.focused=f.head_valid=true;f.head.position={0,1.6f,0};f.hands[1].tracked.valid=f.hands[1].tracked.aimValid=true;}void send(const NativeStrokeSample&s,float pressure){++f.sequence;f.time+=.05;auto&h=f.hands[1].tracked;h.aim.position=h.grip.position=ob::transform(d.frame().state->canvas,{s.origin.x,s.origin.y,s.origin.z});h.aim.orientation=h.grip.orientation=d.frame().state->canvas.orientation;h.trigger=pressure;d.submit(f);if(!d.wait_input())throw std::runtime_error("Selected-key controller samples did not drain");}};
void allocation_rollback(Document &d,bool sculpt){
 d.configure_shape_sculpt(sculpt);done(d);d.select_shape_target(0);done(d);const auto exact=d.copy_scene().encode();
 selection_failure::calls=0;selection_failure::count=true;d.select_shape_target(1);selection_failure::count=false;const auto count=selection_failure::calls;done(d);check(count>0&&count<1000,"Target selection has a bounded measured publication allocation set");d.select_shape_target(0);done(d);
 for(size_t cut=0;cut<count;++cut){const auto before=d.frame();selection_failure::remaining=long(cut);bool denied=false;try{d.select_shape_target(1);}catch(const std::bad_alloc&){denied=true;}catch(...){selection_failure::remaining=-1;throw;}selection_failure::remaining=-1;const auto after=d.frame();if(!denied||after.state->morph_target!=before.state->morph_target||after.state->input_epoch!=before.state->input_epoch||after.state->view_epoch!=before.state->view_epoch||after.state->revision!=before.state->revision||after.surface!=before.surface||d.copy_scene().encode()!=exact)throw std::runtime_error("Selection publication allocation rollback at prefix "+std::to_string(cut));}
 std::cout<<"SELECTION_PERSISTENT_PREFIXES sculpt="<<sculpt<<" count="<<count<<std::endl;d.select_shape_target(1);done(d);check(d.copy_scene().encode()==exact&&d.frame().state->morph_target==1,"Selection retries exactly after all persistent publication failures");
}
}
int main(int argc,char**argv)try{
 if(argc==3&&std::string_view(argv[1])=="--ui-fixture"){source().save(argv[2]);return 0;}
 if(argc==3&&std::string_view(argv[1])=="--inspect"){std::cout<<Scene::load(argv[2]).encode().dump();return 0;}
 if(argc!=2)return 2;const std::filesystem::path out=argv[1];std::filesystem::create_directories(out);auto initial=source();const auto first=initial.encode();Document d;d.replace(initial);done(d);ShapeKeyEdit mirror;mirror.action=ShapeKeyAction::Mirror;mirror.mirror_frames=ShapeKeyMirrorFrames::BaseRelative;d.author_shape(mirror);done(d);const auto mirrored=d.copy_scene();const auto exact=mirrored.encode();check(d.frame().state->morph_target==1,"Actual Mirror initially selects its new converted target");
 auto file=out/"selection.dsculpt";d.save_async(file).get();check(d.undo()&&d.copy_scene().encode()==first&&d.redo()&&d.copy_scene().encode()==exact&&d.frame().state->morph_target==0,"Existing Undo clamp and Redo ephemeral selection semantics remain exact");done(d);
 const auto before=d.frame();const auto lease=d.draft_scene().source;d.select_shape_target(1,lease);done(d);auto after=d.frame();check(after.state->morph_target==1&&after.state->generation==before.state->generation&&after.state->revision==before.state->revision&&after.state->edit_authority==before.state->edit_authority&&after.state->view_epoch==before.state->view_epoch&&after.surface==before.surface,"Off-sculpt selection changes neither Scene source leases nor rendered geometry");check(after.state->input_epoch==before.state->input_epoch+1&&after.state->dirty==before.state->dirty&&after.state->can_undo==before.state->can_undo&&after.state->can_redo==before.state->can_redo&&d.copy_scene().encode()==exact,"Choosing an existing target preserves complete Scene, dirty and history while retiring old input");d.save_async(file).get();check(Scene::load(file).encode()==exact,"Save after ephemeral reselection writes the exact accepted Scene");
 auto epoch=d.frame().state->input_epoch;d.select_shape_target(1,lease);check(d.frame().state->input_epoch==epoch,"Choosing the same target is a true no-op");check(refuses([&]{d.select_shape_target(2,lease);},"existing")&&d.copy_scene().encode()==exact,"Out-of-range target selection refuses without mutation");auto foreign=lease;++foreign.edit_authority;check(refuses([&]{d.select_shape_target(0,foreign);},"source changed"),"Foreign editor authority cannot select a target");foreign=lease;++foreign.revision;check(refuses([&]{d.select_shape_target(0,foreign);},"source changed"),"Stale scene revision refuses even without a topology change");
 allocation_rollback(d,false);allocation_rollback(d,true);auto old=d.frame();d.select_shape_target(0);done(d);after=d.frame();check(after.state->revision==old.state->revision&&after.state->generation==old.state->generation&&after.state->view_epoch==old.state->view_epoch+1&&after.surface->view_epoch==after.state->view_epoch,"Isolated sculpt reselection uses its own settled view endpoint and preserves Scene revision");
 const auto busy=d.draft_scene().source;check(d.begin_native_stroke(),"A real native target session can start on the selected endpoint");check(refuses([&]{d.select_shape_target(1,busy);},"gesture")&&d.frame().state->morph_target==0,"Active target gesture blocks selection before changing its captured target");d.end_native_stroke(false);done(d);d.select_shape_target(1);done(d);auto ray=visible_ray(d);check(d.begin_native_stroke()&&d.sample_native_stroke(ray),"Explicitly reselected converted target accepts a real visible stroke");d.end_native_stroke();d.save_async(out/"reselected-stroke.dsculpt").get();done(d);const auto sculpted=d.copy_scene();const auto&a=*mirrored.active().deformation->morphs,&b=*sculpted.active().deformation->morphs;check(same_values(a.targets[0].delta,b.targets[0].delta)&&!same_values(a.targets[1].delta,b.targets[1].delta),"After Undo/Redo and explicit reselection only the chosen converted target changes");check(sculpted.active().painted->encode()==mirrored.active().painted->encode()&&sculpted.active().deformation->morph_weights==mirrored.active().deformation->morph_weights,"Reselected strokes retain exact Paint and saved mixed weights");check(d.undo()&&d.copy_scene().encode()==exact&&d.redo()&&d.copy_scene().encode()==sculpted.encode(),"No selection-only history command interferes with actual stroke Undo/Redo");done(d);
 // A held controller cannot switch from a chosen endpoint into a new one until
 // a real release has been observed after the selection's new input epoch.
 ray=visible_ray(d);Hand hand(d);hand.send(ray,0);const auto stable=d.copy_scene().encode();d.select_shape_target(0);done(d);hand.send(ray,.8f);check(!d.frame().state->native_pending&&d.copy_scene().encode()==stable,"A trigger held across target reselection cannot leak a new stroke");hand.send(ray,0);hand.send(ray,.8f);check(d.frame().state->native_pending,"A fresh released-then-pressed controller rearms the selected target");hand.f.focused=false;hand.send(ray,.8f);done(d);check(d.copy_scene().encode()==stable,"Focus loss cancels the newly rearmed selected-target draft exactly");
 std::cout<<"PASS "<<checks<<" native shapekey selection checks\n";return 0;
}catch(const std::exception&e){selection_failure::remaining=-1;selection_failure::count=false;std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
